// Signs Android release builds with the Play upload key when it is set up on
// this machine, and keeps the debug key otherwise (local test APKs).
//
// The key and its passwords never enter the repo. They live in a properties
// file outside it, by default ~/.skatehive/android-upload.properties, or
// wherever SKATEHIVE_UPLOAD_PROPERTIES points:
//
//   storeFile=/absolute/path/to/skatehive-upload.keystore
//   storePassword=...
//   keyAlias=upload
//   keyPassword=...
//
// android/ is generated by prebuild, so this edits app/build.gradle there.
const { withAppBuildGradle } = require("expo/config-plugins");

const MARK = "// skatehive-release-signing";

const HELPER = `${MARK}: the Play upload key lives outside the repo.
// A relative SKATEHIVE_UPLOAD_PROPERTIES is relative to the repo root (rootDir is android/), the same base
// scripts/build-android-aab.js uses; Gradle's own working directory is not guaranteed. A relative storeFile
// is relative to the properties file.
def skatehiveUploadProps() {
    def path = System.getenv('SKATEHIVE_UPLOAD_PROPERTIES') ?: "\${System.getProperty('user.home')}/.skatehive/android-upload.properties"
    def f = new File(path)
    if (!f.isAbsolute()) f = new File(rootDir.parentFile, path)
    if (!f.exists()) return null
    def p = new Properties()
    f.withInputStream { p.load(it) }
    def store = new File(p['storeFile'])
    if (!store.isAbsolute()) store = new File(f.parentFile, p['storeFile'])
    p['storeFile'] = store.absolutePath
    return p
}
`;

module.exports = function withAndroidReleaseSigning(config) {
  return withAppBuildGradle(config, (c) => {
    let gradle = c.modResults.contents;
    if (gradle.includes(MARK)) return c;

    const steps = [
      [/\nandroid \{/, `\n${HELPER}\nandroid {`],
      [
        /signingConfigs \{\n(\s+)debug \{/,
        (_m, ind) =>
          `signingConfigs {\n${ind}release {\n${ind}    def p = skatehiveUploadProps()\n` +
          `${ind}    if (p != null) {\n` +
          `${ind}        storeFile file(p['storeFile'])\n` +
          `${ind}        storePassword p['storePassword']\n` +
          `${ind}        keyAlias p['keyAlias']\n` +
          `${ind}        keyPassword p['keyPassword']\n` +
          `${ind}    }\n${ind}}\n${ind}debug {`,
      ],
      [
        /(release \{\n(?:\s*\/\/[^\n]*\n)*\s*)signingConfig signingConfigs\.debug/,
        "$1signingConfig skatehiveUploadProps() != null ? signingConfigs.release : signingConfigs.debug",
      ],
    ];
    for (const [pattern, replacement] of steps) {
      if (!pattern.test(gradle)) {
        throw new Error(`withAndroidReleaseSigning: app/build.gradle no longer matches ${pattern}`);
      }
      gradle = gradle.replace(pattern, replacement);
    }
    c.modResults.contents = gradle;
    return c;
  });
};
